INSERT INTO exercises (id, lesson_id, title, instruction, exercise_type, skill_type, time_limit, max_attempts, ordering, content)
VALUES
    ('40000000-0000-0000-0000-000000000001', NULL, 'IELTS Writing Task 2 - Dev w2_003', 'You should spend about 40 minutes on this task. Write about the following topic: In many countries around the world, rural people are moving to cities, so the population in the countryside is decreasing. Do you think this is a positive or a negative development? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 101, '{"task": "QT_W2_OPINION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000002', NULL, 'IELTS Writing Task 2 - Dev w2_005', 'You should spend about 40 minutes on this task. Write about the following topic: People are against the legalization of euthanasia while other people support it. Discuss both views and give your own opinion. Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 102, '{"task": "QT_W2_OPINION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000003', NULL, 'IELTS Writing Task 2 - Dev w2_008', 'You should spend about 40 minutes on this task. Write about the following topic: In recent years, young people in many countries have chosen to live by themselves. What are the reasons and is it a positive or negative for the development of society? Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 103, '{"task": "QT_W2_DISCUSSION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000004', NULL, 'IELTS Writing Task 2 - Dev w2_009', 'You should spend about 40 minutes on this task. Write about the following topic: Today many people buy imported food, rather than consuming local products. Do advantages outweigh disadvantages? Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 104, '{"task": "QT_W2_ADV_DISADV"}'::jsonb),
    ('40000000-0000-0000-0000-000000000005', NULL, 'IELTS Writing Task 2 - Dev w2_013', 'You should spend about 40 minutes on this task. Write about the following topic: In some countries young people have become richer, healthier and live longer, but they are less happy. What are the causes? What can be done to address this situation? Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 105, '{"task": "QT_W2_PROBLEM_SOLUTION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000006', NULL, 'IELTS Writing Task 2 - Dev w2_014', 'You should spend about 40 minutes on this task. Write about the following topic: Nowadays many people complain that they have difficulty getting enough sleep. What problems can lack of sleep cause ? What can be done about lack of sleep? Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 106, '{"task": "QT_W2_PROBLEM_SOLUTION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000007', NULL, 'IELTS Writing Task 2 - Dev w2_017', 'You should spend about 40 minutes on this task. Write about the following topic: Freshwater is a limited resource in certain regions of the world. Today, the escalating demand has transformed it into a global problem. What are the causes of increasing demand? What measures can governments and individuals take to respond to the problem? " Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 107, '{"task": "QT_W2_PROBLEM_SOLUTION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000008', NULL, 'IELTS Writing Task 2 - Dev w2_018', 'You should spend about 40 minutes on this task. Write about the following topic: Some people say that parents should encourage their children to take part in organised group activities in their free time. Others say that It is important for children to learn how to occupy themselves on their own. Discuss both these views and give your own opinion. Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 108, '{"task": "QT_W2_OPINION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000009', NULL, 'IELTS Writing Task 2 - Dev w2_019', 'You should spend about 40 minutes on this task. Write about the following topic: In the future, more people will choose to go on holidays in their own country and not travel abroad on holiday. Discuss both views and give your advantage and disadvantages? Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 109, '{"task": "QT_W2_DISCUSSION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000010', NULL, 'IELTS Writing Task 2 - Dev w2_022', 'You should spend about 40 minutes on this task. Write about the following topic: In some countries, shopping online is replacing shopping at the store. Do you think it is a positive or negative development Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 110, '{"task": "QT_W2_OPINION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000011', NULL, 'IELTS Writing Task 2 - Dev w2_027', 'You should spend about 40 minutes on this task. Write about the following topic: In some countries, birth rates are falling and experts say that by 2050, older people will be 65% more than children onder 15. What problems might this cause in the future? Can anything be done to solve this issue? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 111, '{"task": "QT_W2_DISCUSSION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000012', NULL, 'IELTS Writing Task 2 - Dev w2_029', 'You should spend about 40 minutes on this task. Write about the following topic: In many countries people are now living longer than ever before. Some people say an ageing population creates problems for governments. Other people think there are benefits if society has more elderly people. To what extent do the advantages of having an ageing population outweigh the disadvantages? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 112, '{"task": "QT_W2_DISCUSSION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000013', NULL, 'IELTS Writing Task 2 - Dev w2_031', 'You should spend about 40 minutes on this task. Write about the following topic: In many cities there is a lack of space to develop and as a result, in order to modernise, old buildings are demolished and replaces with new buildings. What are the disadvantages of knocking down old building? Do the advantages outweigh the disadvantages? Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 113, '{"task": "QT_W2_ADV_DISADV"}'::jsonb),
    ('40000000-0000-0000-0000-000000000014', NULL, 'IELTS Writing Task 2 - Dev w2_035', 'You should spend about 40 minutes on this task. Write about the following topic: The best manager is one who is warm and friendly with their staff. Do agree or disagree? Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 114, '{"task": "QT_W2_OPINION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000015', NULL, 'IELTS Writing Task 2 - Dev w2_039', 'You should spend about 40 minutes on this task. Write about the following topic: Plastics and chemicals are becoming threat to the planet. Discuss its reasons and solution. Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 115, '{"task": "QT_W2_DISCUSSION"}'::jsonb),
    ('40000000-0000-0000-0000-000000000016', NULL, 'IELTS Writing Task 2 - Dev w2_040', 'You should spend about 40 minutes on this task. Write about the following topic: Some people think young people are not suitable for important position in the government while other people think it is a good idea for young people to take on the positions. Discuss both views and give your opinion. Write at least 250 words.', 'PRACTICE', 'WRITING', 2400, 20, 116, '{"task": "QT_W2_OPINION"}'::jsonb)
